mapper.select:
SELECT d.id, d.no, d.warehouse_id, w.code AS warehouse_code, w.name AS warehouse_name, d.reason, d.status, d.audit_time, d.remark, (SELECT COUNT(*) FROM inv_other_in_line l WHERE l.other_in_id = d.id AND l.deleted = 0) AS line_count, (SELECT COALESCE(SUM(l.qty), 0) FROM inv_other_in_line l WHERE l.other_in_id = d.id AND l.deleted = 0) AS total_qty, d.create_time FROM inv_other_in d LEFT JOIN base_warehouse w ON w.id = d.warehouse_id WHERE d.deleted = 0
AND d.status = #{q.status}
AND d.warehouse_id = #{q.warehouseId}
AND d.no LIKE CONCAT('%', #{q.keyword}, '%')
ORDER BY d.id DESC
